// Dictionary engine — no UI, no dependencies, works fully offline on the JSON
// under public/data/ (generated by scripts/build-data.mjs, see its header and
// public/data/dict/manifest.json).
//
// Data layout used here:
//   /data/dict/index-hanzi.json       { type, chars: { <simplifiedChar>: [shard] } }
//   /data/dict/index-hanzi-trad.json  same, keyed by traditional char
//   /data/dict/index-pinyin/<a-z>.json  { <tonelessKey>: [shard] }   (whole word)
//   /data/dict/index-english/<a-z>.json { <englishWord>: [shard] }
//   /data/dict/shards/NNN.json        [{ id, simp, trad, pinyin, pinyinNumeric, defs[] }]
//
// Spanish (derivative CC-CEDICT translations, locale 'es'):
//   /data/es/dict/shards/NNN.json        same NNN as the English shard,
//                                        [{ id, defs[] }] — only translated entries
//   /data/search-es/<a-z>.json           { <spanishWord>: [[id, shard], …] }
// Loaded lazily too, and merged by id: an entry with no translation keeps its
// English defs. A missing Spanish file (404) is normal and cached as "no data".
//
// Shards are fetched lazily on first use and cached (a search touches 1 index
// file + the 1–n shards it points at, never all 115).
//
// Public API (all async):
//   search(query, { limit = 20, spanish = false })
//       Detects hanzi (simp or trad), pinyin ("nǐ hǎo" | "ni3hao3" | "ni hao")
//       and english ("hello"); exact matches rank first. With `spanish`, a
//       Latin query also consults the Spanish index first and every result gets
//       `defsEs` (its translation, by id) when one exists.
//   lookup(word, { spanish = false }) -> entry | null   exact hanzi/pinyin lookup
//   segment(text) -> string[]             longest-match word split (reader)
//   detectType(query) -> 'hanzi' | 'pinyin' | 'latin'
//   configure({ fetch })                  inject a fetch for Node/tests
//   resetCache()                          drop cached shards/indexes
//   distinctDefs(defs, max = 3)           display list: near-duplicates dropped

import { tonelessKey } from './pinyin.js';
import { esTokens } from './es-tokens.js';

const BASE = typeof document === 'undefined' ? '/data/dict' : new URL('data/dict', document.baseURI);
const ES_BASE = typeof document === 'undefined' ? '/data/es/dict' : new URL('data/es/dict', document.baseURI);
const ES_SEARCH_BASE = typeof document === 'undefined' ? '/data/search-es' : new URL('data/search-es', document.baseURI);

const HANZI_RE = /[\u3400-\u9fff\uf900-\ufaff]/;
const TONE_MARK_RE = /[āáǎàēéěèīíǐìōóǒòūúǔùǖǘǚǜ]/i;
/** Tone marks that are also Spanish accents (2nd tone == acute): ambiguous. */
const AMBIGUOUS_TONE_RE = /[áéíóú]/i;
const UNAMBIGUOUS_TONE_RE = /[āǎàēěèīǐìōǒòūǔùǖǘǚǜ]/i;
const TONE_NUM_RE = /[a-zü][1-5]/i;
const LATIN_RE = /^[a-zü\s'1-5]+$/i;

let fetcher = null;
const cache = new Map();
/** letter -> Promise(postings|null) for the Spanish search index. */
const spanishSearchCache = new Map();
/** entry object -> the shard number it lives in (to find its Spanish twin). */
const shardOf = new WeakMap();

/** Inject a fetch implementation (Node tests, workers). Clears the cache. */
export function configure(opts = {}) {
  if (typeof opts.fetch === 'function') fetcher = opts.fetch;
  resetCache();
}

/** Drop every cached index/shard (fetched again on next use). */
export function resetCache() {
  cache.clear();
  spanishSearchCache.clear();
}

function getJSON(rel, base = BASE) {
  const url = `${base}/${rel}`;
  let pending = cache.get(url);
  if (!pending) {
    pending = Promise.resolve()
      .then(() => (fetcher || globalThis.fetch)(url))
      .then((res) => {
        if (!res || res.ok === false) {
          const err = new Error(`dictionary: ${rel} -> ${res && res.status}`);
          err.status = res && res.status;
          throw err;
        }
        return res.json();
      });
    cache.set(url, pending);
    pending.catch(() => cache.delete(url));
  }
  return pending;
}

/** Resolve to null only when the file does not exist; real failures propagate. */
const orNullOn404 = (promise) =>
  promise.catch((err) => {
    if (err?.status === 404) return null;
    throw err;
  });

const shardId = (n) => `shards/${String(n).padStart(3, '0')}.json`;
const letterOf = (s) => (s && /[a-z]/.test(s[0]) ? s[0] : null);

const loadShard = (id) => getJSON(shardId(id));
const loadHanziIndex = () => getJSON('index-hanzi.json');
const loadTradIndex = () => getJSON('index-hanzi-trad.json');
const loadPinyinIndex = (letter) => getJSON(`index-pinyin/${letter}.json`);
const loadEnglishIndex = (letter) => getJSON(`index-english/${letter}.json`);

async function shardsFor(ids) {
  const unique = [...new Set(ids || [])];
  const loaded = await Promise.all(
    unique.map(async (id) => {
      const list = await loadShard(id);
      if (Array.isArray(list)) {
        for (const e of list) if (e && typeof e === 'object') shardOf.set(e, id);
      }
      return list;
    }),
  );
  return loaded.flat();
}

// ---------------------------------------------------------------- spanish

/**
 * Spanish shard `NNN` as a Map(id -> defs[]), or null when it does not exist.
 * A 404 is normal — the entry just keeps its English defs — and is cached as
 * "no data", so it is only fetched once per session.
 */
function esShardDefs(n) {
  if (n == null) return Promise.resolve(null);
  const url = `${ES_BASE}/${shardId(n)}`;
  let pending = cache.get(url);
  if (!pending) {
    pending = Promise.resolve()
      .then(() => (fetcher || globalThis.fetch)(url))
      .then((res) => {
        if (res && res.ok === false) {
          if (res.status === 404) return null; // not translated: normal
          const err = new Error(`dictionary: es shard ${n} -> ${res.status}`);
          err.status = res.status;
          throw err;
        }
        return res.json();
      })
      .then((list) => {
        if (!Array.isArray(list)) return null;
        const map = new Map();
        for (const e of list) if (e && e.id != null && Array.isArray(e.defs)) map.set(e.id, e.defs);
        return map;
      })
      // Only a 404 is a real "no data": a network/5xx failure must not poison
      // the cache for the rest of the session (offline first search).
      .catch((err) => {
        cache.delete(url);
        throw err;
      });
    cache.set(url, pending);
  }
  return pending;
}

/** Spanish search postings (`es/search/<letter>.json`), or null; a 404 is cached. */
function loadSpanishSearch(letter) {
  let pending = spanishSearchCache.get(letter);
  if (!pending) {
    pending = getJSON(`${letter}.json`, ES_SEARCH_BASE).catch((err) => {
      // Feature off when the file does not exist; a network failure is retried.
      if (err?.status === 404) return null;
      throw err;
    });
    spanishSearchCache.set(letter, pending);
    pending.catch(() => spanishSearchCache.delete(letter));
  }
  return pending;
}

/**
 * Attach the Spanish translation of each result, matched by id inside its own
 * (same-numbered) shard. A missing shard, or an entry that was not translated,
 * leaves `defsEs` unset so the caller falls back to `defs` (English) per entry.
 */
async function withSpanish(results) {
  await Promise.all(
    results.map(async (r) => {
      const defs = (await esShardDefs(r.shard))?.get(r.id);
      if (defs && defs.length) r.defsEs = defs;
    }),
  );
  return results;
}

/** Candidate shard ids for a hanzi word, from both the simp and trad indices. */
async function hanziShards(word) {
  const ch = [...word][0];
  if (!ch) return [];
  const ids = [];
  for (const load of [loadHanziIndex, loadTradIndex]) {
    const idx = await orNullOn404(load());
    const list = idx && idx.chars && idx.chars[ch];
    if (list) ids.push(...list);
  }
  return ids;
}

// ---------------------------------------------------------------- detection

/** Coarse query type; `'latin'` still has to be told pinyin from english. */
export function detectType(query) {
  const q = String(query ?? '').trim();
  if (!q) return 'latin';
  if (HANZI_RE.test(q)) return 'hanzi';
  if (TONE_MARK_RE.test(q) || TONE_NUM_RE.test(q)) return 'pinyin';
  return 'latin';
}

/** Does the pinyin index know this (tone-less) latin query? */
async function isPinyin(q) {
  const key = tonelessKey(q);
  const letter = letterOf(key);
  if (!letter) return false;
  const idx = await orNullOn404(loadPinyinIndex(letter));
  if (!idx) return false;
  if (idx[key]) return true;
  return Object.keys(idx).some((k) => k.startsWith(key));
}

/** Is `q` an exact pinyin key ("café" is not: acute accents are Spanish too)? */
async function hasExactPinyin(q) {
  const key = tonelessKey(q);
  const letter = letterOf(key);
  if (!letter) return false;
  const idx = await orNullOn404(loadPinyinIndex(letter));
  return Boolean(idx && idx[key]);
}

// ---------------------------------------------------------------- search

const toResult = (e) => ({
  id: e.id,
  simp: e.simp,
  trad: e.trad,
  pinyinTone: e.pinyin,
  pinyinNum: e.pinyinNumeric,
  defs: e.defs,
  shard: shardOf.get(e),
});

function rank(list, limit) {
  const seen = new Set();
  return list
    .filter((h) => (seen.has(h.e.id) ? false : seen.add(h.e.id)))
    .sort((a, b) => b.score - a.score || a.e.simp.length - b.e.simp.length)
    .slice(0, Math.max(0, limit))
    .map((h) => toResult(h.e));
}

async function searchHanzi(q) {
  const entries = await shardsFor(await hanziShards(q));
  const out = [];
  for (const e of entries) {
    const exact = e.simp === q || e.trad === q;
    const prefix = !exact && (e.simp.startsWith(q) || e.trad.startsWith(q));
    const contains = !exact && !prefix && (e.simp.includes(q) || e.trad.includes(q));
    if (exact) out.push({ e, score: 100 });
    else if (prefix) out.push({ e, score: 70 - Math.min(30, e.simp.length - q.length) });
    else if (contains) out.push({ e, score: 40 - Math.min(20, e.simp.length - q.length) });
  }
  return out;
}

/** Max shards one latin search may fetch (a syllable appears in most shards). */
const MAX_SHARDS = 8;
const capShards = (ids) => [...new Set(ids)].slice(0, MAX_SHARDS);

async function searchPinyin(q) {
  const key = tonelessKey(q);
  const letter = letterOf(key);
  if (!letter) return [];
  const idx = await orNullOn404(loadPinyinIndex(letter));
  if (!idx) return [];

  const ids = [];
  if (idx[key]) {
    ids.push(...idx[key]);
  } else {
    // Prefix expansion only when the exact syllable isn't there (a prefix like
    // "pan" would otherwise pull in "pang"/"pian" entries from most shards).
    for (const [k, list] of Object.entries(idx)) {
      if (ids.length >= 200) break;
      if (k.startsWith(key)) ids.push(...list);
    }
  }
  const entries = await shardsFor(capShards(ids));
  const out = [];
  for (const e of entries) {
    const ek = tonelessKey(e.pinyinNumeric || '');
    if (ek === key) out.push({ e, score: 100 });
    else if (ek.startsWith(key)) out.push({ e, score: 70 - Math.min(30, ek.length - key.length) });
  }
  return out;
}

async function searchEnglish(q) {
  const words = q.toLowerCase().match(/[a-z][a-z'-]*/g) || [];
  if (!words.length) return [];
  const primary = words[0];
  const letter = letterOf(primary);
  if (!letter) return [];
  const idx = await orNullOn404(loadEnglishIndex(letter));
  if (!idx) return [];

  const ids = [];
  const keys = Object.keys(idx);
  for (const k of keys) {
    if (k === primary) ids.push(...idx[k]);
    else if (ids.length < 200 && k.startsWith(primary)) ids.push(...idx[k]);
  }
  const entries = await shardsFor(capShards(ids));
  const wanted = new Set(words);
  const out = [];
  for (const e of entries) {
    let best = 0;
    for (const def of e.defs) {
      const tokens = (def.toLowerCase().match(/[a-z][a-z'-]*/g) || []);
      for (const w of wanted) {
        const at = tokens.indexOf(w);
        if (at === -1) continue;
        // Earlier in the definition wins; a whole-definition hit wins more.
        const score = 100 - at * 5 + (tokens.length === 1 ? 20 : 0);
        if (score > best) best = score;
      }
    }
    if (best > 0) out.push({ e, score: best });
  }
  return out;
}

/**
 * Spanish-word search using the derivative index (word -> shards): look the
 * query word up there, then keep the entries whose Spanish defs contain it.
 * Scores sit above the English ones so a Spanish query surfaces Spanish hits
 * first. Returns [] when there is no Spanish index (feature simply off).
 */
const ES_MAX_SHARDS = 4;

async function searchSpanish(q) {
  const words = esTokens(q);
  if (!words.length) return [];
  const primary = words[0];
  const letter = letterOf(primary);
  if (!letter) return [];
  const idx = await loadSpanishSearch(letter);
  if (!idx) return [];
  // Exact word only: a prefix that is not a word in the definitions can never
  // pass the token filter below, so expanding it just burns requests (M4).
  const pairs = Array.isArray(idx[primary]) ? idx[primary] : null;
  if (!pairs || !pairs.length) return [];

  const order = new Map();
  for (const [id] of pairs) if (!order.has(id)) order.set(id, order.size);
  const shards = [...new Set(pairs.map(([, shard]) => shard))].slice(0, ES_MAX_SHARDS);
  const entries = await shardsFor(shards);
  const wanted = new Set(words);
  const out = [];
  for (const e of entries) {
    if (!order.has(e.id)) continue;
    const defs = (await esShardDefs(shardOf.get(e)))?.get(e.id) || [];
    const tokens = new Set(defs.flatMap(esTokens));
    if (!words.every((w) => tokens.has(w))) continue;
    let best = 0;
    for (const def of defs) {
      const defTokens = esTokens(def);
      for (const w of wanted) {
        const at = defTokens.indexOf(w);
        if (at === -1) continue;
        best = Math.max(best, 100 - at * 5 + (defTokens.length === 1 ? 20 : 0));
      }
    }
    // Relevance (exact/prefix, position, HSK, length, id) is already encoded in
    // the postings order; `best` only nudges within an equal order (REVIEW-3 I6).
    out.push({ e, score: 1000 - order.get(e.id) + Math.min(50, best) / 100 });
  }
  return out;
}

/**
 * Search the dictionary. Query type is auto-detected.
 * @param {string} query
 * @param {{ limit?: number, spanish?: boolean }} [opts] `spanish` (locale es)
 *   consults the Spanish index for a Latin query and adds `defsEs` per result.
 * @returns {Promise<Array<{id:number,simp:string,trad:string,pinyinTone:string,pinyinNum:string,defs:string[],defsEs?:string[]}>>}
 */
export async function search(query, { limit = 20, spanish = false } = {}) {
  const q = String(query ?? '').trim();
  if (!q) return [];
  const type = detectType(q);
  let hits;
  if (type === 'hanzi') hits = await searchHanzi(q);
  else if (spanish && !TONE_NUM_RE.test(q) && !UNAMBIGUOUS_TONE_RE.test(q)) {
    // A Spanish word can look like pinyin ("pan", "año", "café" — the acute is
    // the 2nd tone). Run the Spanish search and, when the query is also an exact
    // pinyin syllable, the pinyin search together: pinyin without tones is the
    // most common way a student types, so it must not be a last resort
    // (REVIEW-3 I5). "ñ" is never pinyin, so that exception stays.
    const exactPinyin = !/ñ/i.test(q) && (await hasExactPinyin(q));
    const [es, py] = await Promise.all([
      searchSpanish(q),
      exactPinyin ? searchPinyin(q) : Promise.resolve([]),
    ]);
    if (es.length || py.length) hits = [...es, ...py];
    else hits = await searchEnglish(q);
  } else if (type === 'pinyin' || (await isPinyin(q))) hits = await searchPinyin(q);
  else hits = await searchEnglish(q);
  const ranked = rank(hits, limit);
  return spanish ? withSpanish(ranked) : ranked;
}

// ---------------------------------------------------------------- lookup

/**
 * Exact lookup by hanzi (simp or trad) or by pinyin word.
 * With `spanish`, the result carries `defsEs` when a translation exists.
 */
export async function lookup(word, { spanish = false } = {}) {
  const q = String(word ?? '').trim();
  if (!q) return null;
  if (detectType(q) === 'hanzi') {
    const entries = await shardsFor(await hanziShards(q));
    const hit = entries.find((e) => e.simp === q || e.trad === q);
    if (!hit) return null;
    const result = toResult(hit);
    return spanish ? (await withSpanish([result]))[0] : result;
  }
  const results = await search(q, { limit: 50, spanish });
  return results[0] || null;
}

/** Exact hanzi match against the entry's own shard set (segment helper). */
async function exactHanzi(word) {
  const entries = await shardsFor(await hanziShards(word));
  return entries.find((e) => e.simp === word || e.trad === word) || null;
}

// ---------------------------------------------------------------- segment

const MAX_WORD = 8;

/**
 * Split text into dictionary words using longest-match, for the reader.
 * Hanzi runs are matched against the dictionary; everything else (latin,
 * digits, punctuation, spaces) is passed through as its own chunk.
 * @returns {Promise<string[]>}
 */
export async function segment(text) {
  const s = String(text ?? '');
  const out = [];
  let buf = '';
  const flush = () => {
    if (buf) { out.push(buf); buf = ''; }
  };
  for (let i = 0; i < s.length;) {
    const ch = s[i];
    if (!HANZI_RE.test(ch)) { buf += ch; i += 1; continue; }
    flush();
    let matched = null;
    for (let len = Math.min(MAX_WORD, s.length - i); len >= 2; len--) {
      const cand = s.slice(i, i + len);
      if (![...cand].every((c) => HANZI_RE.test(c))) continue;
      matched = await exactHanzi(cand);
      if (matched) { out.push(matched.simp); i += len; break; }
    }
    if (!matched) { out.push(ch); i += 1; }
  }
  flush();
  return out;
}

/** Words dropped when comparing two definitions ("to thank" ≈ "thank you"). */
const DEF_STOPWORDS = new Set([
  'a', 'an', 'the', 'to', 'of', 'for', 'in', 'on', 'be', 'is', 'are', 'you', 'it', 'that', 'this',
]);

/** Normalised word set of a definition: lowercase, no punctuation, no plural -s. */
function defWords(def) {
  return new Set(
    String(def ?? '')
      .toLowerCase()
      .replace(/[^a-z\u00e0-\u00ff\s'-]/g, ' ')
      .split(/[\s'-]+/)
      .filter((w) => w && !DEF_STOPWORDS.has(w))
      .map((w) => (w.length > 3 && w.endsWith('s') && !w.endsWith('ss') ? w.slice(0, -1) : w)),
  );
}

/**
 * Trim a definition list for display: drop near-duplicates and cap the count.
 * CC-CEDICT repeats one idea several ways ("to thank / thanks / thank you"),
 * which is noise on a 390 px row. Two definitions count as the same when one's
 * normalised words are a subset of the other's.
 *
 * @param {string[]} defs
 * @param {number} [max=3] most definitions to keep
 * @returns {string[]}
 */
export function distinctDefs(defs, max = 3) {
  const out = [];
  const seen = [];
  for (const def of Array.isArray(defs) ? defs : []) {
    const text = String(def ?? '').trim();
    if (!text) continue;
    const words = defWords(text);
    if (!words.size) continue;
    const sub = (a, b) => [...a].every((w) => b.has(w));
    if (seen.some((k) => sub(words, k) || sub(k, words))) continue;
    seen.push(words);
    out.push(text);
    if (out.length >= Math.max(1, max)) break;
  }
  return out;
}